        radial-gradient(circle at top left, rgba(96, 165, 250, 0.24), transparent 30%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.22), transparent 25%),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

