      margin: 0 0 12px;
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 2.8rem);
      line-height: 1.1;
    }

    .intro {
      margin: 14px 0 0;
      max-width: 52ch;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      margin-top: 28px;
      display: grid;
      gap: 24px;
    }

    .form-field {
      display: grid;
      gap: 14px;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      padding: 0;
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 14px;
    }

    .option-list {
      display: grid;
      gap: 12px;
    }

    .option-card {
      position: relative;
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 16px 18px;
      background: #ffffff;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 18px;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      cursor: pointer;
    }

    .option-card:hover {
      border-color: rgba(37, 99, 235, 0.4);
      box-shadow: 0 10px 24px rgba(37, 99, 235, 0.08);
      transform: translateY(-1px);
    }

    .option-card:focus-within {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px var(--ring);
    }

    .option-card input[type="radio"] {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .option-content {
      display: grid;
      gap: 4px;
    }

    .option-label {
      font-weight: 600;
    }

    .option-note {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .submit-row {
      display: flex;
      align-items: center;
      gap: 14px;
      flex-wrap: wrap;
    }

    button {
      border: 0;
