       flex-wrap: wrap;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 14px 22px;
       font: inherit;
       font-weight: 700;
       color: #ffffff;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       box-shadow: 0 14px 28px rgba(37, 99, 235, 0.25);
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 18px 32px rgba(37, 99, 235, 0.28);
     }

     button:focus-visible {
       outline: 3px solid var(--ring);
       outline-offset: 3px;
     }

     .status-message {
       min-height: 1.5rem;
       color: var(--muted);
       font-size: 0.95rem;
     }

     @media (max-width: 640px) {
       .form-card {
         padding: 24px;
       }
     }
   </style>
 </head>
 <body>
   <div id="root"></div>

   <script>
     const notificationOptions = [
       {
         id: "notification-email",
         value: "Email",
         label: "Email",
         note: "Get updates in your inbox."
       },
       {
         id: "notification-sms",
         value: "SMS",
         label: "SMS",
         note: "Receive short text-message alerts."
       },
       {
         id: "notification-push",
         value: "Push Notifications",
         label: "Push Notifications",
         note: "Stay informed with instant app notifications."
       }
     ];

     function RadioOption({ id, value, label, note }) {
       return `
         <label class="option-card" for="${id}">
           <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
           <span class="option-content">
             <span class="option-label">${label}</span>
             <span class="option-note">${note}</span>
           </span>
         </label>
       `;
     }

     function FormField() {
       return `
         <div class="form-field">
           <fieldset>
             <legend>How do you prefer to receive notifications?</legend>
             <div class="option-list">
               ${notificationOptions.map((option) => RadioOption(option)).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function FormSection() {
       return `
         <section class="form-card" aria-labelledby="page-title">
           <p class="eyebrow">Preferences</p>
           <h1 id="page-title">Choose your notification channel</h1>
           <p class="intro">
             Tell us how you would like to hear from us so we can send updates in the format that fits you best.
           </p>
           <form id="preferences-form">
             ${FormField()}
             <div class="submit-row">
               <button type="submit">Submit</button>
               <div class="status-message" id="status-message" aria-live="polite"></div>
             </div>
           </form>
         </section>
       `;
')
